    size_t num_parameters_bytes;
    ParameterTensors grads;
    void* grads_memory;
    float* m_memory;
    float* v_memory;
    float* master_weights;
    ActivationTensors acts;
    TensorSpec acts_specs[NUM_ACTIVATION_TENSORS];
    void* acts_memory;
    int batch_size;
    int seq_len;
